from ctypes import c_double, c_void_p
import json

# Load the dynamic library
libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define the necessary types and structures
class GSLFunction(ctypes.Structure):
    pass
GSLFunction.__init__(self, _fields_=[
        ('function', ctypes.c_void_p),
        (
            'value', c_double * 1,
        ),
        (
            'eval', c_double * 2,
        ),
    ])

# Define the GSL function prototypes
libgsl.gsl_integration_cquad.argtypes = [ctypes.POINTER(GSLFunction), c_double, c_double, c_double, c_double, ctypes.c_size_t, ctypes.POINTER(c_void_p)]
libgsl.gsl_integration_cquad.restype = c_double

# Define the my_func function prototype
libgsl.my_func.argtypes = [c_double]
libgsl.my_func.restype = c_double

# Create a wrapper for Python callables to be used as GSL functions
def wrap(func):
    def wrapped(x):
        return func(x)
    funcwrapper = GSLFunction(function=ctypes.cast(wrapped, ctypes.c_void_p), value=(c_double * 1)(), eval=(c_double * 2)())
    return funcwrapper

# Define the integration function
def integrate(func, a, b, epsabs, epsrel, workspace_size):
    funcwrapper = wrap(func)
    status = c_void_p.in_dll(libgsl, "gsl_integration_cquad", use_last_error=True)
    result = libgsl.gsl_integration_cquad(
        funcwrapper,
        a,
        b,
        epsabs,
        epsrel,
        workspace_size,
        ctypes.byref(status)
    )
    return json.dumps(
        {
            "Candidate_solution":
                f"integrate({func.__name__}, {a}, {b}, {epsabs}, {epsrel}, {workspace_size}) = {result}
        }
    )
"}

