class GSLMatrix(ctypes.Structure):
    _fields_ = [('self', c_void_p), ('rows', ctypes.c_int), ('cols', ctypes.c_int)]

    def __init__(self, rows, cols):
        self._allocate(rows, cols)

    def _allocate(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.self = gslcblas.gsl_matrix_alloc(rows, cols)

    def free(self):
        gslcblas.gsl_matrix_free(self.self)

    def to_numpy(self):
        arr = np.zeros((self.rows, self.cols), dtype=np.double)
        gslcblas.gsl_matrix_get(self.self, c_void_p(arr.data), 0, 0, self.rows, self.cols)
        return arr.tolist()

def list_to_ctypes_matrix(lst):
    matrix = GSLMatrix(len(lst), len(lst[0]))
    for i in range(matrix.rows):
        for j in range(matrix.cols):
            matrix.self.contents.data[i * matrix.cols + j] = lst[i][j]
    return matrix

def compute_covariance(jacobian, epsrel):
    matrix = list_to_ctypes_matrix(jacobian)
    covar_matrix = GSLMatrix(matrix.rows, matrix.cols)
