def cholesky_decomp(matrix):
    if not is_positive_definite(matrix):
        raise ValueError("Matrix is not positive definite")
    L = GSLMatrix(*matrix.shape)
    L.data = ctypes.cast(ctypes.addressof(L.data.contents), ctypes.POINTER(ctypes.c_double*int(matrix.size1*matrix.size2)))
    status = gsl.gsl_linalg_cholesky_decomp(matrix.size1, L.data, matrix.data)
    if status:
        raise ValueError("Cholesky decomposition failed")
    return np.frombuffer(L.data, dtype=np.double).reshape((L.size1, L.size2))

def decompose_cholesky(matrix):
    result = cholesky_decomp(np.array(matrix, dtype=np.double))
    return np.tolist(result)
